CREATE OR REPLACE PROCEDURE sp(para_Start_year integer, para_Club_name text, para_Club_ID integer, para_Player_ID integer, para_Occupation text, para_Votes integer)
LANGUAGE plpgsql
AS $$
BEGIN
    DELETE FROM club WHERE Club_ID <= para_Club_ID + 7;
    UPDATE club SET Club_name = 'phase_9' WHERE Club_ID > para_Club_ID + 7;
    UPDATE club SET Region = para_Club_name WHERE Club_ID > para_Club_ID + 7 AND Start_year < para_Start_year;

    DELETE FROM player WHERE Votes < para_Votes;
    UPDATE player SET Occupation = 'log_phase_9' WHERE Votes >= para_Votes;
    IF para_Start_year >= 2011 THEN
        UPDATE player SET Sponsor_name = para_Club_name WHERE Votes >= para_Votes;
    ELSE
        UPDATE player SET Sponsor_name = para_Club_name WHERE Votes >= para_Votes AND Player_ID = para_Player_ID;
    END IF;
END;
$$;

